const {execFileSync}=require("child_process");
const fs=require("fs");
const EXE="/workspace/dataset/test13_executable";
const OUT="/workspace/probes/string.jsonl";
const seen=new Set(fs.readFileSync(OUT,"utf8").trim().split("\n").map(l=>{const o=JSON.parse(l);return o.a+" "+o.b;}));
const lines=[];
function PRAW(at,bt){
  const key=at+" "+bt; if(seen.has(key)){process.stdout.write("DUP  "+bt.slice(0,100)+"\n");return;} seen.add(key);
  let out,exit;
  try{out=execFileSync(EXE,["--a",at,"--b",bt],{encoding:"utf8",stdio:["ignore","pipe","pipe"],timeout:20000});exit=0;}
  catch(e){out=e.stdout==null?"":e.stdout;exit=(e.status==null?-1:e.status);}
  lines.push(JSON.stringify({a:at,b:bt,out,exit}));
  const o=out.split("\n"); const brief=exit!==0?("EXIT"+exit+" out="+JSON.stringify(out)):(o[1]+"/"+o[2]+" ["+o[0].replace("Validator","")+"]");
  process.stdout.write(brief.padEnd(30)+" b="+bt.slice(0,120)+"  a="+at.slice(0,45)+"\n");
}
function P(a,b){ PRAW(JSON.stringify(a),JSON.stringify(b)); }
function flush(){ if(lines.length) fs.appendFileSync(OUT,lines.join("\n")+"\n"); console.log("APPENDED",lines.length); }
module.exports={P,PRAW,flush};

const {P,PRAW,flush}=require("/workspace/gen3.js");

console.log("=== A: $schema resolution ===");
P("abc",{$schema:"http://example.com/unknown",minLength:5});
