const {P,PRAW,flush}=require("/workspace/gen3.js");

console.log("=== E: regex compile edges (instance IS a string) ===");
const pats=[
 "[^]",            // JS: any char; Python: unterminated set -> crash
 "[]",             // Python: unterminated set -> crash ; JS: never matches
 "[]a]",
 "a{",             // Python: literal '{' ; JS /u: SyntaxError
 "a}",
 "{2}",            // leading quantifier on nothing
 "a{2,3}{2}",      // multiple repeat
