P(5,{pattern:"[^]"});
P(5,{pattern:"[]"});
P(5,{pattern:"a{2,3}{2}"});
P(true,{pattern:"["});
P(null,{pattern:"["});
P([],{pattern:"["});
P({},{pattern:"["});

