const {P,PRAW,flush}=require("/workspace/gen3.js");
const D={3:"http://json-schema.org/draft-03/schema#",4:"http://json-schema.org/draft-04/schema#",6:"http://json-schema.org/draft-06/schema#",7:"http://json-schema.org/draft-07/schema#",19:"https://json-schema.org/draft/2019-09/schema",20:"https://json-schema.org/draft/2020-12/schema"};
