sweep({a:"ab"},{patternProperties:{"^a$":{minLength:5,maxLength:1}}});
sweep("ab",{exclusiveMinimum:true,minLength:5});

console.log("=== H: error-count applicator edges ===");
P("ab",{if:{minLength:1}});
P("ab",{if:{minLength:99},then:{minLength:5}});
P("ab",{if:{minLength:99},else:{minLength:5,maxLength:1}});
P("ab",{if:{minLength:1},then:{minLength:5},else:{minLength:9}});
P("ab",{then:{minLength:5},else:{minLength:9}});
P("ab",{allOf:[{minLength:5},{maxLength:1},{pattern:"^z$"}]});
